#!/usr/bin/env python3
"""FMDX warm monitor: VPS RTX 4090 runner cmd (CRLF) that samples one checkpoint on a list of sets x seeds with the FROZEN bb_sample.py
(FM-free, DDIM-50, eta 0, EMA; prereg A2/A4.3(e) device rule). Idempotent (skips existing <out>.json).
Usage: vps_sample_cmd.py SPEC.json NUMBER > NNN_fxm_<tag>.cmd
SPEC = {"tag","ckpt_rel","out_rel","seeds":[0,1,2],"sets":[{"name","gt_rel","render_rel","subset":null|1000}]}  (all *_rel are under $VPS_ROOT\\uhwr\\stage)"""
import json, sys
spec = json.load(open(sys.argv[1])); num = int(sys.argv[2])
assert (411 <= num <= 439 and num not in (420, 430)) or 900 <= num <= 999, num  # 900-999 = dispatcher job labels (dispatch\\ready), not runner numbers  # monitor range: sorts before the 440-446 arm cmds (runner = lexical order)
w = lambda p: "%STG%\\" + p.replace("/", "\\")
L = ["@echo off", f"REM FMDX warm monitor sampling cmd {num} tag {spec['tag']} (generated by vps_sample_cmd.py, fmdx_monitor_v1)",
     "set ROOT=$VPS_ROOT\\uhwr", "set PY=C:\\ProgramData\\miniconda3\\envs\\uhwr\\python.exe", "set STG=%ROOT%\\stage", "set CODE=%ROOT%\\code\\fmdx_backbone_v1",
     "set PYTHONPATH=%ROOT%\\winshim;%ROOT%\\repos\\nagamatsu\\src;%CODE%;%CODE%\\vendor;%STG%\\exp\\FMD\\xs\\code\\pydeps_timm",
     "set PYTHONIOENCODING=utf-8", "set PYTHONDONTWRITEBYTECODE=1", f"set OUT={w(spec['out_rel'])}", "if not exist %OUT% mkdir %OUT%",
     "%PY% -c \"import hashlib,sys,os;os.chdir(r'%CODE%');bad=[l.split()[1] for l in open('SHA256SUMS.txt') if hashlib.sha256(open(l.split()[1],'rb').read()).hexdigest()!=l.split()[0]];print('code sha bad',bad);sys.exit(1 if bad else 0)\"",
     "if errorlevel 1 exit /b 31", f"if not exist {w(spec['ckpt_rel'])} exit /b 32", "echo %DATE% %TIME% start >> %OUT%\\job_history.txt"]
for s in spec["sets"]:
    for sd in spec["seeds"]:
        stem = f"{s['name']}__{spec['tag']}__seed{sd}"
        sub = f" --subset {s['subset']} --subset-seed 0" if s.get("subset") else ""
        L += [f"if not exist %OUT%\\{stem}_preds.json (",
              f"  %PY% -u %CODE%\\bb_sample.py --ckpt {w(spec['ckpt_rel'])} --render {w(s['render_rel'])} --gt-npz {w(s['gt_rel'])}{sub} --seed {sd} --sampling-timesteps 50 --ddim-eta 0 --batch-size 250 --out %OUT%\\{stem}_preds.npz >> %OUT%\\sample.log 2>&1",
              f"  if errorlevel 1 (echo FAILED {stem} >> %OUT%\\job_history.txt & exit /b 33)", ")"]
L += ["echo %DATE% %TIME% end >> %OUT%\\job_history.txt", "exit /b 0"]
sys.stdout.buffer.write(("\r\n".join(L) + "\r\n").encode())
